lemma ListsInterlace.count_sub_one_le_count {lower upper : List ℝ}
    (h : ListsInterlace lower upper) (a : ℝ) :
    lower.count a - 1 ≤ upper.count a

lemma PolynomialInterlaces.interlacer_rootUpperBound
    {q p : ℝ[X]} (h : PolynomialInterlaces q p) {x : ℝ}
    (hpx : IsRootUpperBound p x) : IsRootUpperBound q x

@[simp] lemma eval_polynomialWeightedSum {ι : Type*}
    (s : Finset ι) (w : ι → ℝ) (p : ι → ℝ[X]) (x : ℝ) :
    (polynomialWeightedSum s w p).eval x = ∑ i ∈ s, w i * (p i).eval x

theorem signVariations_le_of_coeffSignRefines {p q : ℝ[X]}
    (h : CoeffSignRefines p q) :
    p.signVariations ≤ q.signVariations

theorem eval_sub_ne_zero_of_convex_isRoot
    {p q : ℝ[X]}
    (hdisjoint : ∀ x : ℝ, ¬ (p.IsRoot x ∧ q.IsRoot x))
    {t x : ℝ}
    (ht : (t • p + (1 - t) • q).IsRoot x) :
    p.eval x - q.eval x ≠ 0

theorem subsingleton_setOf_convex_isRoot
    {p q : ℝ[X]}
    (hdisjoint : ∀ x : ℝ, ¬ (p.IsRoot x ∧ q.IsRoot x))
    (x : ℝ) :
    Set.Subsingleton
      {t : ℝ | (t • p + (1 - t) • q).IsRoot x}

theorem MvStableOrZero.diagonalize {σ : Type*}
    {p : MvPolynomial σ ℂ} (hp : MvStableOrZero p) :
    UnivariateStableOrZero (diagonalize p)

theorem MvStableOrZero.mul {σ : Type*} {p q : MvPolynomial σ ℂ}
    (hp : MvStableOrZero p) (hq : MvStableOrZero q) :
    MvStableOrZero (p * q)

theorem MvStableOrZero.rename {σ τ : Type*}
    {p : MvPolynomial σ ℂ} (hp : MvStableOrZero p) (f : σ → τ) :
    MvStableOrZero (MvPolynomial.rename f p)

theorem UnivariateStableOrZero.derivative {p : ℂ[X]}
    (hp : UnivariateStableOrZero p) :
    UnivariateStableOrZero p.derivative

theorem realRooted_of_map_upperStable {p : ℝ[X]}
    (hp : UnivariateUpperStable (p.map Complex.ofRealHom)) :
    CommutatorTheorem.RealRooted p

lemma averageCharpoly_natDegree_le {n r k : ℕ}
    (A : Fin k → Matrix (Fin n) (Fin n) ℂ) (a : Fin r) :
    (averageCharpoly A a).natDegree ≤ n

theorem averageTrace_eq_inv_mul_sum_trace {n r k : ℕ}
    (A : Fin k → Matrix (Fin n) (Fin n) ℂ) (a : Fin r) :
    averageTrace A a = (r : ℂ)⁻¹ * ∑ j : Fin k, (A j).trace

lemma compressedFamily_isHermitian {n r k : ℕ}
    {A : Fin k → Matrix (Fin n) (Fin n) ℂ}
    (hA : ∀ j, (A j).IsHermitian) (c : Coloring n r) (a : Fin r) (j : Fin k) :
    (compressedFamily A c a j).IsHermitian

@[simp] lemma familySum_apply {n k : ℕ}
    (A : Fin k → Matrix (Fin n) (Fin n) ℂ) (i l : Fin n) :
    familySum A i l = ∑ j : Fin k, A j i l

lemma familySum_isHermitian {n k : ℕ}
    {A : Fin k → Matrix (Fin n) (Fin n) ℂ} (hA : ∀ j, (A j).IsHermitian) :
    (familySum A).IsHermitian

lemma jointMaskedCompression_isHermitian {n r k : ℕ}
    {A : Fin k → Matrix (Fin n) (Fin n) ℂ}
    (hA : ∀ j, (A j).IsHermitian) (c : Coloring n r) (a : Fin r) :
    (jointMaskedCompression A c a).IsHermitian

@[simp] lemma secondNewtonKernel_diag {n : ℕ}
    (M : Matrix (Fin n) (Fin n) ℂ) (i : Fin n) :
    secondNewtonKernel M i i = 0

theorem mvStableOrZero_of_complexStable {σ : Type*}
    {p : MvPolynomial σ ℂ} (hp : ComplexStable p) :
    MvStableOrZero p

lemma reciprocal_gap_pair_nonneg {A ai aj : ℝ}
    (hA : 0 < A) (hai : 0 < ai) (haj : 0 < aj)
    (haiA : ai < A) (hajA : aj < A) :
    let ti := ai * A / (A - ai)
    let tj := aj * A / (A - aj)
    0 ≤ (ti - tj) * (aj * ti - ai * tj)

lemma rootBarrierPotential_eq_sum_roots {p : ℝ[X]} (hp : RealRooted p) {b : ℝ}
    (hb : p.eval b ≠ 0) :
    rootBarrierPotential p b = (p.roots.map fun r ↦ 1 / (b - r)).sum

lemma RealRooted.derivative_strictRootUpperBound
    {p : ℝ[X]} (hp : RealRooted p) (hdeg : 0 < p.natDegree) {x : ℝ}
    (hx : IsStrictRootUpperBound p x) : IsStrictRootUpperBound p.derivative x

lemma rootBarrierPotential_pos_of_strictRootUpperBound
    {p : ℝ[X]} (hp : RealRooted p) (hdeg : 0 < p.natDegree) {x : ℝ}
    (hx : IsStrictRootUpperBound p x) : 0 < rootBarrierPotential p x

theorem coordinatePolynomial_roots_neg {p : MvPolynomial σ ℝ} {z : σ → ℝ}
    (hz : AboveRoots p z) (j : σ) {r : ℝ}
    (hr : r ∈ (coordinatePolynomial p z j).roots) : r < 0
